//! Simulation-based calibration of the adaptive-procedure posterior report.
//!
//! The derived whole-procedure report for a Beta-Bernoulli procedure states a posterior mean
//! gap of zero and a credible interval whose reading is "calibrated under the prior
//! predictive of the whole procedure, stopping rule included". That reading is a claim about
//! the procedure, not about one fixed truth: the truth is drawn from the prior, the data are
//! generated by the adaptive procedure run to its data-dependent end, and the equal-tailed
//! credible interval at the stopping look is scored against the drawn truth. Nothing here is
//! measured at implementation time: every test is `#[ignore]`d and runs only at the final
//! measurement step, and no interval or posterior claim is licensed until its record exists.
//!
//! Design (whole method, truth, nominal level, support range, probes):
//!
//! * Procedure: two-arm Beta-Bernoulli Thompson sampling, uniform priors, looks at half and
//!   at all of `n`, stopping when the posterior probability that an arm is best exceeds the
//!   threshold. The threshold is the axis: 0.90, 0.95 and 0.99.
//! * Truth: each arm's success probability is drawn independently from the prior, once per
//!   replicate, so the nominal level is exact for a correct posterior and any stopping rule
//!   that depends on the data only through the posterior.
//! * Score: the equal-tailed 95% credible interval of the treatment arm at the stopping look
//!   against that replicate's drawn success probability.
//! * Support range under test: `n` on the three-point grid around 200 and the three
//!   thresholds above. Boundary probe: the 0.99 threshold, where most replicates run to the
//!   horizon and the final look is the stopping look.
//! * Positive control: the same procedure scored against a fixed truth is
//!   `adaptive_inference_calibration.rs`; an interval that covers there and fails here (or
//!   the reverse) isolates the prior-predictive reading from the fixed-truth one.
//!
//! The record vocabulary below is the one the fixed-truth designs of the neighbouring suite
//! declare; the interval is the same construction, so a record differs only in its truth.
//!
//! SPDX-License-Identifier: MIT OR Apache-2.0

#![cfg(feature = "calibration-internal")]
#![allow(
    clippy::cast_precision_loss,
    clippy::cast_possible_truncation,
    reason = "bounded simulation sizes and small indices"
)]

#[path = "../../antecedent/tests/common/calibration.rs"]
mod calibration;
#[path = "common/candidate_calibration.rs"]
mod candidate;

use std::sync::Arc;

use antecedent_core::{CalibrationBasis, ExecutionContext};
use antecedent_estimate::adaptive_inference::{
    ArmCounts, bayesian_posterior, beta_credible_interval_internal,
};
use calibration::{CoverageTally, RecordKey, grid_n, map_replicates, n_sim, uniform};

fn ctx(seed: u64) -> ExecutionContext {
    ExecutionContext::for_tests(seed)
}

fn basis(rows: usize) -> CalibrationBasis {
    let a = |text: &str| Arc::<str>::from(text);
    CalibrationBasis::new(
        [
            a("AdaptiveExperimentContrast"),
            a("NotApplicable"),
            a("fixed"),
            a("adaptive_trial_history"),
            a("Bayesian"),
            a("adaptive.thompson_beta_bernoulli.posterior"),
            a("posterior_quantile"),
            a(""),
            a("adaptive_assignment_stopped_by_posterior_rule"),
            a("beta_bernoulli.uniform_prior"),
            a("arm_success_probability:treatment"),
        ],
        0.95,
        a("point"),
        rows as u64,
        None,
        None,
        0.0,
    )
}

/// Looks at half of the sample and at all of it.
fn look_sizes(n: usize) -> [usize; 2] {
    [n / 2, n]
}

struct Stopped {
    counts: [ArmCounts; 2],
    units: usize,
}

/// Thompson sampling run to its data-dependent end against the given truth.
fn thompson_to_stopping(truth: [f64; 2], n: usize, stop_probability: f64, seed: u64) -> Stopped {
    let mut next = uniform(seed, 1);
    let mut counts = [ArmCounts { successes: 0, failures: 0 }; 2];
    let looks = look_sizes(n);
    let mut units = 0;
    for unit in 0..n {
        let posterior = bayesian_posterior(1.0, 1.0, &counts, &ctx(seed)).expect("posterior");
        let arm = usize::from(next() >= posterior.arms[0].probability_best);
        if next() < truth[arm] {
            counts[arm].successes += 1;
        } else {
            counts[arm].failures += 1;
        }
        units = unit + 1;
        if looks.contains(&units) {
            let at_look = bayesian_posterior(1.0, 1.0, &counts, &ctx(seed)).expect("posterior");
            let best = at_look.arms.iter().map(|a| a.probability_best).fold(0.0, f64::max);
            if best > stop_probability {
                break;
            }
        }
    }
    Stopped { counts, units }
}

/// One simulation-based calibration design: the truth of each replicate is a draw from the
/// prior, the procedure runs to its stopping look, and the interval is scored against it.
fn prior_predictive_design(test: &'static str, dgp: &'static str, stop_probability: f64) {
    let n = grid_n(200);
    let mut tally =
        CoverageTally::for_record(RecordKey { test, dgp, interval: "posterior_quantile" }, 0.95);
    let results = map_replicates(n_sim(), |replicate| {
        let seed = calibration::grid_seed(0x7b_0000 + replicate);
        // The truth stream is its own tagged stream: it never shares a coordinate with the
        // assignment or outcome stream of the procedure.
        let mut prior = uniform(seed, 2);
        let truth = [prior(), prior()];
        let stopped = thompson_to_stopping(truth, n, stop_probability, seed);
        let posterior =
            bayesian_posterior(1.0, 1.0, &stopped.counts, &ctx(seed)).expect("posterior");
        (stopped.units, beta_credible_interval_internal(&posterior.arms[1], 0.95), truth[1])
    });
    for (units, interval, truth) in results {
        candidate::bind(&mut tally, &basis(units));
        tally.record(interval, truth);
    }
    tally.assert();
}

#[test]
#[ignore = "calibration: run only at the final measurement step"]
fn thompson_posterior_prior_predictive_stop_090_l95() {
    prior_predictive_design(
        "thompson_posterior_prior_predictive_stop_090_l95",
        "two_bernoulli_arms_truth_from_uniform_prior_thompson_posterior_probability_stop_0.90",
        0.90,
    );
}

#[test]
#[ignore = "calibration: run only at the final measurement step"]
fn thompson_posterior_prior_predictive_stop_095_l95() {
    prior_predictive_design(
        "thompson_posterior_prior_predictive_stop_095_l95",
        "two_bernoulli_arms_truth_from_uniform_prior_thompson_posterior_probability_stop_0.95",
        0.95,
    );
}

#[test]
#[ignore = "calibration: run only at the final measurement step"]
fn thompson_posterior_prior_predictive_stop_099_boundary_l95() {
    prior_predictive_design(
        "thompson_posterior_prior_predictive_stop_099_boundary_l95",
        "two_bernoulli_arms_truth_from_uniform_prior_thompson_posterior_probability_stop_0.99",
        0.99,
    );
}
